import urllib.request, urllib.parse, json
base='https://geo.salvador.ba.gov.br/imageserver/rest/services/Hosted/mdt_apcp_centro_reclass_10m_r/ImageServer'
def get(url):
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
 with urllib.request.urlopen(req,timeout=30) as r:return json.load(r)
meta=get(base+'?f=pjson')
for k in ['name','serviceDescription','description','pixelSizeX','pixelSizeY','bandCount','pixelType','minValues','maxValues','meanValues','stdvValues','objectIdField','capabilities']:
 print('META',k,meta.get(k))
print('SPATIAL_REFERENCE',meta.get('spatialReference'))
print('EXTENT',meta.get('extent'))
# Origin UTM24S obtained by transforming the project's recorded WGS84 origin.
ox=552825.064; oy=8565629.266
points={
 'ORIGIN_PROJECT':(0.0,0.0),
 'LOW_ACCESS_PISO':(-40.431,43.761),
 'TOWER_HEAD_CENTER':(-47.1903,50.1044),
 'HIGH_ENTRY_PISO':(-2.5779,8.2384),
 'HIGH_GALLERY':(-5.2817,10.7757),
}
for name,(x,y) in points.items():
 geom={'x':ox+x,'y':oy+y,'spatialReference':{'wkid':31984}}
 params={'geometry':json.dumps(geom,separators=(',',':')),'geometryType':'esriGeometryPoint','returnGeometry':'false','returnCatalogItems':'false','f':'json'}
 url=base+'/identify?'+urllib.parse.urlencode(params)
 try:
  d=get(url)
  print('IDENTIFY',name,'XY',round(ox+x,3),round(oy+y,3),'VALUE',d.get('value'),'NAME',d.get('name'),'PROPS',d.get('properties'))
 except Exception as e: print('IDENTIFY_ERROR',name,repr(e))
